import React from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { Toaster } from "react-hot-toast";
import { AuthProvider } from "./context/AuthContext";
import { CartProvider } from "./context/CartContext";
import Navbar from "./components/Navbar";
import Footer from "./components/Footer";
import CartSidebar from "./components/CartSidebar";
import WhatsAppButton from "./components/WhatsAppButton";
import Home from "./pages/Home";
import Products from "./pages/Products";
import ProductDetail from "./pages/ProductDetail";
import Cart from "./pages/Cart";
import Checkout from "./pages/Checkout";
import Login from "./pages/Login";
import UserDashboard from "./pages/UserDashboard";
import AdminLayout from "./pages/admin/AdminLayout";
import AdminDashboard from "./pages/admin/AdminDashboard";
import ProductManagement from "./pages/admin/ProductManagement";
import OrderManagement from "./pages/admin/OrderManagement";
import CustomerManagement from "./pages/admin/CustomerManagement";
import ReviewManagement from "./pages/admin/ReviewManagement";
import ColorManagement from "./pages/admin/ColorManagement";
import MobileBottomNav from "./components/MobileBottomNav";
import ScrollToTop from "./components/ScrollToTop";

function MainLayout({ children }) {
  return (
    <>
      <Navbar />
      <CartSidebar />
      <main>{children}</main>
      <Footer />
      <WhatsAppButton />
      <MobileBottomNav />
    </>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <CartProvider>
          <Toaster
            position="top-center"
            toastOptions={{
              duration: 3000,
              style: { borderRadius: "12px", fontSize: "14px" },
            }}
          />
          <ScrollToTop />
          <Routes>
            {/* Public routes */}
            <Route path="/" element={<MainLayout><Home /></MainLayout>} />
            <Route path="/products" element={<MainLayout><Products /></MainLayout>} />
            <Route path="/product/:id" element={<MainLayout><ProductDetail /></MainLayout>} />
            <Route path="/cart" element={<MainLayout><Cart /></MainLayout>} />
            <Route path="/checkout" element={<MainLayout><Checkout /></MainLayout>} />
            <Route path="/login" element={<Login />} />
            <Route path="/dashboard/*" element={<MainLayout><UserDashboard /></MainLayout>} />

            {/* Static pages */}
            <Route path="/about" element={<MainLayout><StaticPage title="About Us" content="We are JAI SHREE DRYFRUITS, committed to bringing you the finest quality dry fruits and nuts from around the world." /></MainLayout>} />
            <Route path="/contact" element={<MainLayout><ContactPage /></MainLayout>} />
            <Route path="/faq" element={<MainLayout><StaticPage title="FAQs" content="Find answers to common questions about our products, shipping, and returns." /></MainLayout>} />
            <Route path="/shipping" element={<MainLayout><StaticPage title="Shipping Policy" content="We ship pan-India. Free shipping on orders above ₹499. Delivery in 3-5 business days." /></MainLayout>} />
            <Route path="/returns" element={<MainLayout><StaticPage title="Return & Refund Policy" content="We offer a 7-day hassle-free return policy. Contact us within 7 days of delivery for returns." /></MainLayout>} />
            <Route path="/privacy" element={<MainLayout><StaticPage title="Privacy Policy" content="Your privacy is important to us. We never sell or share your personal data." /></MainLayout>} />
            <Route path="/terms" element={<MainLayout><StaticPage title="Terms & Conditions" content="By using our website, you agree to our terms of service." /></MainLayout>} />

            {/* Admin routes */}
            <Route path="/admin" element={<AdminLayout />}>
              <Route index element={<AdminDashboard />} />
              <Route path="products" element={<ProductManagement />} />
              <Route path="orders" element={<OrderManagement />} />
              <Route path="customers" element={<CustomerManagement />} />
              <Route path="reviews" element={<ReviewManagement />} />
              <Route path="colors" element={<ColorManagement />} />
            </Route>

            {/* 404 */}
            <Route path="*" element={<MainLayout><NotFound /></MainLayout>} />
          </Routes>
        </CartProvider>
      </AuthProvider>
    </BrowserRouter>
  );
}

function StaticPage({ title, content }) {
  return (
    <div className="max-w-3xl mx-auto px-4 py-16 min-h-[50vh]">
      <h1 className="font-serif text-3xl font-bold text-brand-brown mb-4">{title}</h1>
      <div className="w-12 h-1 bg-brand-gold rounded-full mb-6" />
      <p className="text-gray-600 leading-relaxed">{content}</p>
    </div>
  );
}

function ContactPage() {
  return (
    <div className="max-w-4xl mx-auto px-4 py-16 min-h-[50vh]">
      <h1 className="font-serif text-3xl font-bold text-brand-brown mb-4 text-center">Contact Us</h1>
      <div className="w-12 h-1 bg-brand-gold rounded-full mb-10 mx-auto" />
      <div className="grid md:grid-cols-2 gap-8">
        <div>
          <h2 className="font-semibold text-brand-brown mb-4">Get In Touch</h2>
          <div className="space-y-4">
            <input className="input-field" placeholder="Your Name" />
            <input className="input-field" type="email" placeholder="Your Email" />
            <input className="input-field" placeholder="Subject" />
            <textarea className="input-field resize-none" rows={4} placeholder="Your Message" />
            <button className="btn-primary w-full">Send Message</button>
          </div>
        </div>
        <div className="space-y-4">
          <div className="bg-brand-cream rounded-2xl p-5">
            <p className="font-semibold text-brand-brown mb-2">📞 Phone</p>
            <p className="text-gray-600">+91 75685 77968</p>
            <p className="text-gray-600">+91 99500 62186</p>
          </div>
          <div className="bg-brand-cream rounded-2xl p-5">
            <p className="font-semibold text-brand-brown mb-2">📧 Email</p>
            <p className="text-gray-600">info@jaishreegryfruits.com</p>
          </div>
          <div className="bg-brand-cream rounded-2xl p-5">
            <p className="font-semibold text-brand-brown mb-2">⏰ Business Hours</p>
            <p className="text-gray-600">Mon–Sat: 9:00 AM – 7:00 PM</p>
          </div>
          <a href="https://wa.me/917568577968?text=Hello! I need help." target="_blank" rel="noreferrer"
            className="block bg-[#25D366] text-white p-4 rounded-2xl font-semibold text-center hover:bg-[#20B858] transition-colors">
            💬 Chat on WhatsApp
          </a>
        </div>
      </div>
    </div>
  );
}

function NotFound() {
  return (
    <div className="min-h-[60vh] flex flex-col items-center justify-center text-center px-4">
      <p className="text-6xl mb-4">🔍</p>
      <h1 className="font-serif text-3xl font-bold text-brand-brown mb-2">Page Not Found</h1>
      <p className="text-gray-400 mb-6">The page you're looking for doesn't exist.</p>
      <a href="/" className="btn-primary">Go Home</a>
    </div>
  );
}
